/** Shared column helpers for the conventions in docs/spec/04_DATA_MODEL.md §0. */
import { customType, timestamp, uuid } from "drizzle-orm/pg-core";

/** Case-insensitive text (Postgres citext extension, created in migration 0002). */
export const citext = customType<{ data: string }>({
  dataType() {
    return "citext";
  },
});

/**
 * id + created_at/updated_at per spec §0. IDs are UUIDv7 generated by the app
 * (Better Auth generateId / repositories), so there is no DB default for id.
 * updated_at is trigger-maintained (migration 0002).
 */
export const baseColumns = {
  id: uuid("id").primaryKey(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};
